import{z as p,x as A,o as E,c as d,q as o,j as s,D as e,d as r,s as i,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"2PC 的实现细节","description":"","frontmatter":{"title":"2PC 的实现细节","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dt-2pc-implementation.md","filePath":"cs/dt-2pc-implementation.md","lastUpdated":1791063341000}'),l={name:"cs/dt-2pc-implementation.md"};function m(c,a,C,F,D,u){const B=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="_2pc-的实现细节" tabindex="-1">2PC 的实现细节 <a class="header-anchor" href="#_2pc-的实现细节" aria-label="Permalink to &quot;2PC 的实现细节&quot;">​</a></h1><div class="epigraph"><p>协议图只画两轮消息；实现里多出来的东西——prepared 日志、不确定窗口、启发式决定——才是两阶段提交的真实成本。</p><footer>—— 据 Gray, Notes on Data Base Operating Systems, 1978；Gray and Reuter, Transaction Processing, 1993 整理</footer></div><p><a href="/cs/qo-case-map">上一课</a>给「查询优化深化」收束：诊断沿数据流逆行——先看估计与实际之比，再查统计，再查尺子，最后才轮到改写；每层修复配一个判据，没有判据的修复是化妆。查询优化的判据收了档，事务这条线的判据更硬：提交要么发生、要么没发生。本课是「分布式事务深化」的第一课，打开协议图下面的实现账：prepare 应答前先落什么盘、决策记在哪、不确定窗口里锁归谁管、悬挂事务由谁收拾。主干课的 <a href="/cs/spanner-truetime">Spanner 与 TrueTime</a> 给过跨组 2PC 的外观，本课补的是任何实现都躲不开的内部序。后课的 Percolator 式与 Calvin 式路线，都默认你已知道这套账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干只给了 canCommit、commit、abort 三句话。实现要回答的全是「先写日志还是先回消息」：参与者应答 yes 之前，必须先把 prepared 记录连同 redo/undo 信息刷盘——否则应答之后崩溃，恢复时既不能提交也不能回滚，还占着锁。协调者收齐 yes 后，先写决策记录再广播：广播可以丢，决策不能丢，丢了全组无人有权收场。缺口是把两轮消息变成一条<strong>崩溃安全的日志序</strong>。每一步的先后顺序就是正确性本身；顺序对了，剩下的都只是延迟与吞吐问题，顺序错了，崩溃恢复时系统连「自己决定过什么」都无从谈起。</p><p><span class="marginnote">固定税目：约两轮消息加三处强制刷盘——参与者 prepared、协调者 decision、参与者结局记录。跨洋链路一轮往返按百毫秒计，这段时间事务的锁全部持有；吞吐按锁持有时间的倒数掉，不是按 CPU 掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>账目走一遍。参与者收到 prepare：写 prepared 记录、刷盘、回 yes，锁从此保留到结局到达。协调者收齐：写 decision 记录、刷盘、广播 commit 或 abort。参与者收到结局：写结局记录、释放锁、回执。消息要幂等：协调者恢复后重发决定，参与者可能已提交过，重复收到 commit 不能产生第二次对外效果——用日志里的状态去重。悬挂事务（in-doubt）：协调者迟迟不回时，参与者不能自定结局，只能反复查询、等协调者所在共识组换主补发决定，或超时后由管理员做「启发式决定」；他定的方向若与协调者相反，系统只能记录不一致并告警，因为已对外公布的提交不可撤销。</p>',8)),(E(),s(n,null,{default:e(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8D%8F%E8%B0%83%E8%80%85%E5%8F%91%20prepare%22%5D%20--%3E%20PL%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%E5%86%99%20prepared%20%E6%97%A5%E5%BF%97%E5%B9%B6%E5%88%B7%E7%9B%98%22%5D%0A%20%20PL%20--%3E%20Y%5B%22%E5%9B%9E%20yes%EF%BC%8C%E9%94%81%E4%BF%9D%E7%95%99%22%5D%0A%20%20Y%20--%3E%20DL%5B%22%E5%8D%8F%E8%B0%83%E8%80%85%E5%86%99%20decision%20%E6%97%A5%E5%BF%97%E5%B9%B6%E5%88%B7%E7%9B%98%22%5D%0A%20%20DL%20--%3E%20BC%5B%22%E5%B9%BF%E6%92%AD%20commit%20%E6%88%96%20abort%22%5D%0A%20%20BC%20--%3E%20RL%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%E5%86%99%E7%BB%93%E5%B1%80%E6%97%A5%E5%BF%97%EF%BC%8C%E9%87%8A%E6%94%BE%E9%94%81%22%5D%0A%20%20CR%5B%22%E5%8D%8F%E8%B0%83%E8%80%85%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20ID%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%20in-doubt%EF%BC%9A%E9%94%81%E6%8C%82%E7%9D%80%22%5D%0A%20%20ID%20--%3E%20FX%5B%22%E6%9F%A5%E8%AF%A2%20%2F%20%E5%85%B1%E8%AF%86%E7%BB%84%E6%8D%A2%E4%B8%BB%20%2F%20%E8%B6%85%E6%97%B6%E5%90%AF%E5%8F%91%E5%BC%8F%E5%86%B3%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"优化全部指向「能不能少写、少问、少等」。Presumed Abort：abort 是可以默认的结局——参与者超时未听说协调者，就自行回滚并忘掉 prepared 记录，因为「没消息」与「决定 abort」不可分辨；commit 没有默认答案，「没消息」也可能是「决定还没做」，不能 presume。协调者换主：把协调者状态放进共识组（Spanner 让锁表与提交记录由 Paxos 组持有），不确定窗口从「等一个进程」缩成「等一次选主」，这正是主干口径「共识复制 commit 决策」的兑现。三阶段提交想再进一步，在 prepare 后插一轮 pre-commit，让参与者提前知道「大概率提交」；代价是三轮消息，而且异步网络分区下仍要靠协调者超时收场，工程上极少有人用这一轮去换那一点恢复速度。",-1)),(E(),s(n,null,{default:e(()=>[i(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20TO%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%20prepared%20%E5%90%8E%E8%B6%85%E6%97%B6%E6%9C%AA%E6%94%B6%E5%88%B0%E6%B6%88%E6%81%AF%22%5D%20--%3E%20Q1%7B%22%E8%83%BD%E9%BB%98%E8%AE%A4%E4%BB%80%E4%B9%88%E7%BB%93%E5%B1%80%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22abort%20%E5%8F%AF%20presume%22%7C%20PA%5B%22%E8%87%AA%E8%A1%8C%E5%9B%9E%E6%BB%9A%E5%B9%B6%E5%BF%98%E6%8E%89%20prepared%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20Q1%20--%3E%7C%22commit%20%E4%B8%8D%E5%8F%AF%20presume%22%7C%20NC%5B%22%E6%B2%A1%E6%B6%88%E6%81%AF%20%3D%20%E5%86%B3%E5%AE%9A%20abort%20%E6%88%96%E8%BF%98%E6%B2%A1%E5%86%B3%E5%AE%9A%EF%BC%8C%E6%97%A0%E6%B3%95%E5%8C%BA%E5%88%86%22%5D%0A%20%20NC%20--%3E%20WAIT%5B%22%E9%94%81%E7%BB%A7%E7%BB%AD%E6%8C%82%E7%9D%80%EF%BC%8C%E6%9F%A5%E8%AF%A2%E6%88%96%E7%AD%89%E9%80%89%E4%B8%BB%22%5D%0A%20%20PA%20--%3E%20SAFE%5B%22%E4%B8%A4%E7%A7%8D%E4%B8%96%E7%95%8C%E5%9C%A8%E5%8F%82%E4%B8%8E%E8%80%85%E8%A7%86%E8%A7%92%E5%AE%8C%E5%85%A8%E4%B8%80%E6%A0%B7%EF%BC%9A%E5%AE%89%E5%85%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">数字实例：固定税目算一遍——两轮消息跨洋各约 100 ms，加上三处强制刷盘每次几毫秒，一次跨库事务的锁要持有约 200 ms 以上。单机事务全程微秒级，两者差五六个数量级；吞吐按锁持有时间的倒数掉，这就是「能不用分布式事务就不用」的算术根据。</span></p><p><span class="marginnote">直觉类比：不确定窗口像网购后物流失联——商家说「考虑退款还是发货」，然后没了消息。你既不能拆包也不能退回（不知道最终决定），只能占着收货位干等。「启发式决定」就是等了三天你自作主张拆了包，结果商家其实决定了退款——系统只能记录这笔不一致并告警。</span></p><p><span class="marginnote">常见误区：初学者容易以为 2PC 卡住只是「消息丢了，重发就行」。真正的问题是参与者无权私自定结局：「没收到消息」可能是协调者还没做出决定，也可能只是消息丢了——参与者无法区分这两种世界，所以哪怕重发有用，也只能先挂着锁等。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不复述共识协议本身，不重算 <a href="/cs/spanner-truetime">Spanner 与 TrueTime</a> 的时钟账，也不把 Saga 补偿当成提交协议——补偿是业务失败后的应用层动作，语义与原子提交不在同一层。XA 是接口名，不是第四种协议，它的 prepare/commit 只是这套日志序的函数签名。后课默认：任何「分布式事务」产品，底下要么是这套账，要么把协议整个换掉——下一课看把协调者塞进数据表的做法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实现核心是日志序：先 prepared 刷盘再应答，先 decision 刷盘再广播；两轮消息加三处强制刷盘是固定税。</li><li>不确定窗口里锁必须保留；悬挂事务只能查询、换主或超时启发式，不能私自定结局。</li><li>Presumed Abort 让 abort 免决策日志；commit 没有默认答案，不能 presume。</li><li>决策状态进共识组，阻塞窗缩成选主窗；3PC 多一轮消息换不来分区安全。</li><li>出处：Gray 1978；Gray and Reuter 1993；Mohan 与 Lindsay 的 presumed abort；Corbett et al. 2012。</li></ul>',7))])}const b=p(l,[["render",m]]);export{P as __pageData,b as default};
